commands.text:
export LC_ALL=C
echo "=== Корень / ==="
findmnt -no SOURCE,FSTYPE,SIZE,USED,AVAIL,TARGET / 2>/dev/null || df -h /
echo
echo "--- df -h / ---"
df -h /
echo
echo "=== Все разделы: какой сколько занимает ==="
lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT
echo
ROOT_SRC=$(findmnt -no SOURCE / 2>/dev/null)
FSTYPE=$(findmnt -no FSTYPE / 2>/dev/null)
echo "Система стоит на $ROOT_SRC, файловая система $FSTYPE"
# btrfs приписывает к устройству сабволум (/dev/xxx[/root]) - отрезаем его
CLEAN=${ROOT_SRC%%\[*}
if [ "$CLEAN" != "$ROOT_SRC" ]; then echo "Без имени сабволюма это просто $CLEAN"; fi
ROOT_SRC=$CLEAN
PK=$(lsblk -no PKNAME "$ROOT_SRC" 2>/dev/null)
PNUM=$(echo "$ROOT_SRC" | grep -o '[0-9]*$')
if [ -z "$PK" ] || [ -z "$PNUM" ]; then
echo "Корень стоит не на обычном разделе (похоже на LVM или raid) - эта команда для таких не подойдет."
exit 0
fi
DISK="/dev/$PK"
echo "Дальше смотрим диск $DISK, раздел номер $PNUM"
echo
echo "=== Неразмеченное место (MiB) ==="
parted -s "$DISK" unit MiB print free 2>/dev/null || echo "parted недоступен"
echo
echo "=== Неразмеченное место (GB) ==="
parted -s "$DISK" unit GB print free 2>/dev/null || true
echo
echo "=== Итог: можно ли расширить ==="
parted -s "$DISK" unit MiB print free 2>/dev/null | awk -v p="$PNUM" '
/Free Space/ {
s=$1; e=$2; gsub(/MiB/, "", s); gsub(/MiB/, "", e);
if (found && s+0 >= root_end) { free=e-s; ok=1; exit }
next
}
/^ *[0-9]+/ {
if ($1 == p) { end=$3; gsub(/MiB/, "", end); root_end=end+0; found=1 }
next
}
END {
if (!found) { print("Итог: не нашел корневой раздел в таблице - посмотри вывод parted выше и разберись вручную."); exit }
if (ok && free+0 >= 100) {
printf("За корнем свободно %.0f MiB (это примерно %.1f ГБ) - место есть, можно расширять.\n", free, free/1024);
print("Итог: запускай команду расширения - она отдаст все это место под корень.");
} else {
if (ok) printf("За корнем виден только крошечный хвостик %.0f MiB - это не место, а погрешность разметки.\n", free);
print("Итог: расширять нечего - все место уже отдано под систему.");
}
}
'
case "$FSTYPE" in ext4|btrfs|xfs) echo "Файловая система $FSTYPE подходит - команда расширения с ней справится.";; *) echo "ВНИМАНИЕ: с файловой системой $FSTYPE команда расширения не справится - она умеет только ext4, btrfs и xfs."; exit 0;; esac
